class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        M = max(groups)
        best = [-1] * (M + 1)
        seen = set()
        for j, e in enumerate(elements):
            if e in seen:
                continue
            seen.add(e)
            if e > M:
                continue
            for m in range(e, M + 1, e):
                if best[m] == -1:
                    best[m] = j
        return [best[g] for g in groups]
